import{_ as t,o as e,c as o,a0 as c}from"./chunks/framework.Bmhw_dvp.js";const l=JSON.parse('{"title":"环境变量","description":"","frontmatter":{},"headers":[],"relativePath":"advanced/env.md","filePath":"advanced/env.md","lastUpdated":1793354072000}'),r={name:"advanced/env.md"};function a(i,d,_,n,T,s){return e(),o("div",null,[...d[0]||(d[0]=[c('<h1 id="环境变量" tabindex="-1">环境变量 <a class="header-anchor" href="#环境变量" aria-label="Permalink to &quot;环境变量&quot;">​</a></h1><p>配置分两类：启动时读取的环境变量，以及运行时可改、存在数据库里的设置。</p><h2 id="后端" tabindex="-1">后端 <a class="header-anchor" href="#后端" aria-label="Permalink to &quot;后端&quot;">​</a></h2><table tabindex="0"><thead><tr><th>变量</th><th>说明</th><th>默认值</th></tr></thead><tbody><tr><td><code>PORT</code></td><td>后端服务端口</td><td><code>3333</code></td></tr><tr><td><code>HOST</code></td><td>监听地址</td><td>空（IPv4 / IPv6 双栈）</td></tr><tr><td><code>CONFIG_DIR</code></td><td>数据根目录</td><td><code>&lt;项目根&gt;/config</code></td></tr><tr><td><code>DATABASE_URL</code></td><td>SQLite 文件路径（相对 <code>CONFIG_DIR</code>）</td><td><code>&lt;config&gt;/dev.sqlite</code></td></tr><tr><td><code>SQLITE_WAL</code></td><td>设 <code>0</code> 退回 <code>journal_mode=delete</code></td><td>启用 WAL</td></tr><tr><td><code>CORS_ORIGIN</code></td><td>CORS 允许来源，逗号分隔</td><td><code>*</code></td></tr><tr><td><code>JWT_ACCESS_SECRET</code></td><td>Access Token 密钥（生产宜显式设置）</td><td>自动生成并写入 <code>config/jwt-secrets.json</code></td></tr><tr><td><code>JWT_REFRESH_SECRET</code></td><td>Refresh Token 密钥（生产宜显式设置）</td><td>同上</td></tr><tr><td><code>JWT_ACCESS_EXPIRES_IN</code></td><td>Access Token 有效期</td><td><code>1h</code></td></tr><tr><td><code>JWT_REFRESH_EXPIRES_IN</code></td><td>Refresh Token 有效期</td><td><code>30d</code>（guest 恒为 1h / 7d）</td></tr><tr><td><code>RTMP_PORT</code></td><td>RTMP 推流端口</td><td><code>3334</code></td></tr><tr><td><code>HTTP_FLV_PORT</code></td><td>HTTP-FLV 拉流端口（内部，经 <code>/live</code> 反代）</td><td><code>3335</code></td></tr><tr><td><code>NMS_BIND</code></td><td>内置媒体服务监听地址</td><td><code>0.0.0.0</code></td></tr><tr><td><code>NMS_HTTP_FLV_URL</code></td><td>指向外部媒体服务，设置后不再内嵌</td><td>空</td></tr><tr><td><code>STREAM_PUSH_ENABLED</code></td><td>设为 <code>0</code> 时完全不启动推流服务，不监听 3334/3335</td><td>开启</td></tr><tr><td><code>SERVER_HOST</code></td><td>生成 OBS 推流地址时使用的主机名</td><td>空（取请求 Host 去端口）</td></tr><tr><td><code>EMBY_CLIENT_NAME</code></td><td>Emby / Jellyfin 客户端标识</td><td><code>ZViewer</code></td></tr><tr><td><code>ZVIEWER_UPDATE_SOURCE</code></td><td>运维兜底更新源 <code>github</code> / <code>gitcode</code> / <code>mirror</code>，优先于后台开关</td><td>空</td></tr></tbody></table><p>单文件版的配置写在 <code>config/</code> 下的环境文件；Docker 用 <code>-e</code> 或 compose <code>environment</code> 注入。</p><p><strong>JWT 密钥自举</strong>：未设环境变量时读 <code>config/jwt-secrets.json</code>（长度 ≥32 才采信），仍无则自动生成 64 位 hex 写回。生产环境固定密钥可避免重启后登录态失效。</p><h2 id="语音聊天-livekit" tabindex="-1">语音聊天（LiveKit） <a class="header-anchor" href="#语音聊天-livekit" aria-label="Permalink to &quot;语音聊天（LiveKit）&quot;">​</a></h2><p>语音由伴生的 LiveKit 承载，默认无需配置：信令经 <code>/rtc</code> 反代，媒体走 <code>3333/udp</code>，公网 IP 经 STUN 自动发现。以下变量用于特殊网络环境。</p><table tabindex="0"><thead><tr><th>变量</th><th>说明</th><th>默认值</th></tr></thead><tbody><tr><td><code>LIVEKIT_API_KEY</code></td><td>接入凭证签名密钥</td><td><code>devkey</code></td></tr><tr><td><code>LIVEKIT_API_SECRET</code></td><td>接入凭证签名密钥</td><td><code>zviewer-dev-secret</code></td></tr><tr><td><code>LIVEKIT_API_HOST</code></td><td>服务端 API 与 <code>/rtc</code> 反代的上游地址</td><td><code>http://127.0.0.1:3336</code></td></tr><tr><td><code>LIVEKIT_URL</code></td><td>客户端连接地址；留空按请求头推导，跟随页面域名与协议</td><td>空（自动推导）</td></tr><tr><td><code>LIVEKIT_EXTERNAL</code></td><td>设为 <code>1</code> 跳过伴生服务，连接外置 LiveKit</td><td><code>0</code></td></tr><tr><td><code>LIVEKIT_BIND</code></td><td>伴生服务监听地址</td><td><code>::</code>（双栈）</td></tr><tr><td><code>LIVEKIT_NODE_IP</code></td><td>ICE 广播地址；留空时自动 STUN 发现（需可出网），NAT 复杂环境可手动指定公网 IP</td><td>空（自动）</td></tr><tr><td><code>LIVEKIT_RTC_TCP_PORT</code></td><td>ICE/TCP 端口，与 UDP 同时发布；设 <code>0</code> 关闭该通道</td><td><code>3337</code></td></tr><tr><td><code>LIVEKIT_TURN_DOMAIN</code></td><td>TURN/TLS 域名，与下面两项同时设置时启用 3338 兜底中继</td><td>—</td></tr><tr><td><code>LIVEKIT_TURN_CERT</code></td><td>TURN TLS 证书路径（必须正式证书）</td><td>—</td></tr><tr><td><code>LIVEKIT_TURN_KEY</code></td><td>TURN TLS 私钥路径</td><td>—</td></tr></tbody></table><p>UDP 直连与 TURN 中继并行尝试，TURN 只作兜底，不影响直连延迟。完整关系见<a href="/advanced/voice">语音聊天链路</a>。</p><h2 id="前端构建" tabindex="-1">前端构建 <a class="header-anchor" href="#前端构建" aria-label="Permalink to &quot;前端构建&quot;">​</a></h2><p>构建期变量在打包时写进产物，运行时改不了。</p><table tabindex="0"><thead><tr><th>变量</th><th>说明</th><th>默认值</th></tr></thead><tbody><tr><td><code>VITE_API_URL</code></td><td>API 基础地址</td><td>空（<code>window.location.origin</code>）</td></tr><tr><td><code>VITE_SOCKET_URL</code></td><td>Socket.IO 地址</td><td>空（同上）</td></tr><tr><td><code>VITE_FLV_BASE_URL</code></td><td>OBS 推流模式 HTTP-FLV 拉流地址</td><td><code>/live</code>（后端反代到媒体服务）</td></tr><tr><td><code>VITE_RTMP_PORT</code></td><td>OBS 推流端口提示</td><td><code>3334</code></td></tr></tbody></table><p>开发模式下 Vite 会把 <code>/api</code>、<code>/socket.io</code>、<code>/live</code> 代理到后端，无需配置 <code>VITE_API_URL</code>。运行时可在顶栏「自定义后端地址」覆盖，值存于 localStorage：<code>zviewer-custom-api-url</code>、<code>zviewer-custom-socket-url</code>、<code>zviewer-custom-flv-base-url</code>、<code>zviewer-custom-rtmp-port</code>。</p><h2 id="数据库" tabindex="-1">数据库 <a class="header-anchor" href="#数据库" aria-label="Permalink to &quot;数据库&quot;">​</a></h2><p>只有 SQLite 一种：<code>config/dev.sqlite</code>，WAL 模式，纯 Go 驱动、无原生依赖。表结构由 <code>schema.sql</code> 定义，启动时只校验不建表——新机器必须先跑 <code>npm run db:init</code>，缺表会直接退出。</p><h2 id="运行时可调项-管理后台" tabindex="-1">运行时可调项（管理后台） <a class="header-anchor" href="#运行时可调项-管理后台" aria-label="Permalink to &quot;运行时可调项（管理后台）&quot;">​</a></h2><p>这些设置存库、经管理后台修改：注册模式、建房权限、权限矩阵、一起听默认音量、LiveKit 外部地址、多页面登录（测试）、公告自动弹出、Beta 功能与规则源 / CMS 源、<code>dashDisabled</code>、B站默认解析参数、无人房间自动清理（<code>autoDeleteInactiveRooms</code> + <code>autoDeleteAfterHours</code>，默认 24 小时）。通过 <code>/api/admin/settings</code> 修改，前端启动时经 <code>/api/auth/public-settings</code> 拉取。</p><p>更新源开关（镜像 / GitHub）不进数据库，网页端写 <code>config/update-source.json</code>，桌面端写用户配置目录的 <code>settings.json</code>。</p>',19)])])}const I=t(r,[["render",a]]);export{l as __pageData,I as default};
